using System.Text;
using System.Text.Json;

namespace Mcs.Compiler;

/// <summary>
/// Per-version Minecraft data (blocks, block states, items, entities, effects), generated by tools/gen_mcdata.py
/// from Mojang's data generator reports. Every entry carries a bitmask of the version groups it exists in.
/// </summary>
public static class McData
{
    public sealed record StateProp(int Mask, List<string> Values);
    public sealed record BlockInfo(int Mask, Dictionary<string, StateProp> Props);

    public static readonly string[] GroupIds;
    public static readonly Dictionary<string, BlockInfo> Blocks = new();
    public static readonly Dictionary<string, Dictionary<string, int>> Registries = new();

    /// Renamed IDs (old ↔ new). Used to fall back to the other name when an ID doesn't exist in a version.
    public static readonly Dictionary<string, Dictionary<string, string>> Aliases = new()
    {
        ["entities"] = Bidi(("boat", "oak_boat"), ("chest_boat", "oak_chest_boat")),
        ["blocks"] = Bidi(("grass", "short_grass"), ("chain", "iron_chain")),
        ["items"] = Bidi(("grass", "short_grass"), ("chain", "iron_chain"), ("scute", "turtle_scute")),
        ["effects"] = new(),
    };

    static Dictionary<string, string> Bidi(params (string a, string b)[] pairs)
    {
        var d = new Dictionary<string, string>();
        foreach (var (a, b) in pairs) { d[a] = b; d[b] = a; }
        return d;
    }

    static McData()
    {
        using var s = typeof(McData).Assembly.GetManifestResourceStream("mcdata.json")!;
        using var doc = JsonDocument.Parse(s);
        var root = doc.RootElement;
        GroupIds = root.GetProperty("groups").EnumerateArray().Select(e => e.GetString()!).ToArray();
        foreach (var b in root.GetProperty("blocks").EnumerateObject())
        {
            var props = new Dictionary<string, StateProp>();
            foreach (var p in b.Value.GetProperty("p").EnumerateObject())
                props[p.Name] = new StateProp(p.Value.GetProperty("v").GetInt32(), p.Value.GetProperty("values").EnumerateArray().Select(v => v.GetString()!).ToList());
            Blocks[b.Name] = new BlockInfo(b.Value.GetProperty("v").GetInt32(), props);
        }
        foreach (var kind in new[] { "items", "entities", "effects" })
            Registries[kind] = root.GetProperty(kind).EnumerateObject().ToDictionary(e => e.Name, e => e.Value.GetInt32());
        Registries["blocks"] = Blocks.ToDictionary(kv => kv.Key, kv => kv.Value.Mask);
    }

    public static int GroupIndex(TargetProfile p) => Array.FindIndex(Versions.Groups, g => g.Format == p.Format);

    /// Human-readable version range of a mask, e.g. "1.21.4 – 26.3"
    public static string Describe(int mask)
    {
        var parts = new List<string>();
        for (int i = 0; i < Versions.Groups.Length; i++)
        {
            if ((mask >> i & 1) == 0) continue;
            int j = i;
            while (j + 1 < Versions.Groups.Length && (mask >> (j + 1) & 1) != 0) j++;
            parts.Add(i == j ? Versions.Groups[i].Name : $"{Versions.Groups[i].First} – {Versions.Groups[j].Last}");
            i = j;
        }
        return parts.Count == 0 ? "none" : string.Join(", ", parts);
    }

    public static string Pascal(string id)
    {
        var sb = new StringBuilder();
        foreach (var part in id.Split('_', StringSplitOptions.RemoveEmptyEntries))
            sb.Append(char.ToUpperInvariant(part[0])).Append(part.AsSpan(1));
        var s = sb.ToString();
        return s.Length > 0 && char.IsDigit(s[0]) ? "_" + s : s;
    }
}

/// <summary>Generates C# declarations for EntityType and every block (BlockLib) from McData.</summary>
public static class PreludeGen
{
    static string? cached;

    public static string Source => cached ??= Build();

    static string Build()
    {
        var sb = new StringBuilder();

        // ---- EntityType (summonable entity types)
        sb.Append("namespace EntityLib {\n public enum EntityType {\n");
        foreach (var (id, mask) in McData.Registries["entities"].OrderBy(e => e.Key))
            if (id is not ("player" or "fishing_bobber"))
                sb.Append($"  [MCS.McId(\"{id}\")] {McData.Pascal(id)},\n");
        sb.Append(" }\n}\n");

        // ---- Block state enums: one enum per state name, containing the union of its non-bool/non-int values
        var enumValues = new SortedDictionary<string, List<string>>();
        foreach (var b in McData.Blocks.Values)
            foreach (var (name, p) in b.Props)
                if (StateType(p.Values) == "enum")
                {
                    var list = enumValues.TryGetValue(name, out var l) ? l : enumValues[name] = new();
                    foreach (var v in p.Values) if (!list.Contains(v)) list.Add(v);
                }
        var blockClassNames = McData.Blocks.Keys.Select(McData.Pascal).ToHashSet();
        var enumName = enumValues.Keys.ToDictionary(k => k, k =>
        {
            string n = McData.Pascal(k);
            return blockClassNames.Contains(n) || n is "Block" ? n + "State" : n;
        });

        sb.Append("namespace BlockLib {\n");
        foreach (var (state, values) in enumValues)
        {
            sb.Append($" public enum {enumName[state]} {{ ");
            sb.Append(string.Join(", ", values.Select(v => $"[MCS.McId(\"{v}\")] {McData.Pascal(v)}")));
            sb.Append(" }\n");
        }

        // ---- One class per block
        foreach (var (id, info) in McData.Blocks.OrderBy(b => b.Key))
        {
            string cls = McData.Pascal(id);
            sb.Append($" [MCS.McId(\"{id}\")] public sealed class {cls} : Block {{ public {cls}() : base(0) {{ }}");
            foreach (var (name, p) in info.Props.OrderBy(p => p.Key))
            {
                string type = StateType(p.Values) switch { "bool" => "bool", "int" => "int", _ => enumName[name] };
                string prop = McData.Pascal(name);
                if (prop == cls) prop += "State";
                sb.Append($" [MCS.State(\"{name}\", \"{string.Join(",", p.Values)}\")] public {type} {prop} {{ get; set; }}");
            }
            sb.Append(" }\n");
        }
        sb.Append("}\n");
        return sb.ToString();
    }

    public static string StateType(List<string> values) =>
        values.All(v => v is "true" or "false") ? "bool"
        : values.All(v => int.TryParse(v, out _)) ? "int"
        : "enum";
}
